<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';
use InaudisVote\Core\Authorization;use InaudisVote\Core\Csrf;use InaudisVote\Core\Navigation;use InaudisVote\Services\ElectionService;use InaudisVote\Services\LiveControlService;use InaudisVote\Services\ResultService;use InaudisVote\Services\WitnessService;
$user=Authorization::requireRoles(['admin','witness']);$id=(int)($_GET['election_id']??0);$election=ElectionService::find($id);
if(!$election||!Authorization::canReviewElection($user,$id,(int)$election['organization_id'])){http_response_code(403);exit('No autorizado.');}
$error=null;$message=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!Csrf::validate($_POST['_csrf']??null))$error='Solicitud inválida.';
 else try{$action=(string)($_POST['action']??'');if($user['role']==='witness'&&$action==='checkpoint'){$hash=WitnessService::checkpoint($id,(string)$_POST['stage'],(int)$user['id']);$message='Hito fiscalizado. Evidencia SHA-256: '.$hash;}elseif($user['role']==='admin'&&$action==='create_assign'){WitnessService::createAndAssign($id,$_POST,(int)$user['id']);$message='Ministro de Fe creado y asignado a esta votación.';}elseif($user['role']==='admin'&&$action==='assign'){WitnessService::assign($id,(int)$_POST['user_id'],(int)$user['id']);$message='Ministro de Fe asignado.';}elseif($user['role']==='admin'&&$action==='remove'){WitnessService::remove($id,(int)$_POST['user_id'],(int)$user['id']);$message='Asignación retirada.';}else throw new RuntimeException('Acción no autorizada.');}catch(Throwable $exception){$error=$exception->getMessage();}
}
$live=LiveControlService::snapshot($id);$witnesses=WitnessService::forElection($id);$available=WitnessService::available((int)$election['organization_id']);$checks=WitnessService::checkpoints($id);$nextStage=$user['role']==='witness'?WitnessService::nextStage($id,(int)$user['id']):null;
$stageLabels=['setup_reviewed'=>'Configuración revisada','census_verified'=>'Padrón verificado','opening_attested'=>'Apertura constatada','closing_attested'=>'Cierre constatado','results_attested'=>'Resultados constatados'];
$stageStates=['setup_reviewed'=>['draft','scheduled','open'],'census_verified'=>['draft','scheduled','open'],'opening_attested'=>['open'],'closing_attested'=>['closed'],'results_attested'=>['closed']];$canCertifyNext=$nextStage!==null&&in_array($election['status'],$stageStates[$nextStage]??[],true);
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fiscalización | QUORUM</title><link rel="stylesheet" href="/assets/quorum.css"><link rel="stylesheet" href="/assets/live-control.css"></head><body class="vota-ui"><div class="v-shell">
<?php Navigation::sidebar($user, 'witness', $id, $election['title']); ?>
<div class="v-main"><header class="v-topbar"><?php if($user['role']==='admin'):?><a class="v-link" href="/control.php?election_id=<?=$id?>">← Centro de control</a><?php endif;?><span style="flex:1"></span><a class="v-link" href="/logout.php">Salir</a></header><main class="v-content">
<div class="v-headrow"><div><div class="v-kicker">Fiscalización electoral</div><h1 class="v-title"><?=htmlspecialchars($election['title'])?></h1><div class="v-accent-line"></div><p class="v-subtitle">Revisión ordenada de hitos y evidencia de integridad del proceso.</p></div><span class="v-live-pill <?=$election['status']==='open'?'is-live':''?>">● <?=htmlspecialchars(strtoupper($election['status']))?></span></div>
<?php if($message):?><div class="v-alert v-alert-ok"><?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="v-alert v-alert-error"><?=htmlspecialchars($error)?></div><?php endif;?>
<section class="v-stats" style="grid-template-columns:repeat(3,1fr)"><div class="v-card v-stat"><strong><?=$live['eligible']?></strong><span class="v-muted">Habilitados</span></div><div class="v-card v-stat teal"><strong><?=$live['voted']?></strong><span class="v-muted">Votaron</span></div><div class="v-card v-stat orange"><strong><?=$live['participation']?>%</strong><span class="v-muted">Participación</span></div></section>
<div class="v-grid-2"><section class="v-card v-pad"><h2>Ministros de Fe asignados</h2><?php foreach($witnesses as $witness):?><div class="v-row"><div><strong><?=htmlspecialchars($witness['name'])?></strong><div class="v-muted"><?=htmlspecialchars($witness['email'])?></div></div><?php if($user['role']==='admin'):?><form method="post" onsubmit="return confirm('¿Retirar esta asignación?');"><?=Csrf::input()?><input type="hidden" name="action" value="remove"><input type="hidden" name="user_id" value="<?=$witness['id']?>"><button class="v-btn v-btn-danger">Retirar</button></form><?php endif;?></div><?php endforeach;?><?php if(!$witnesses):?><p class="v-muted">Sin Ministro de Fe asignado.</p><?php endif;?><?php if($user['role']==='admin'):?><form method="post" class="v-stack" style="margin-top:18px"><?=Csrf::input()?><input type="hidden" name="action" value="assign"><select class="v-field" name="user_id" required><option value="">Selecciona un Ministro de Fe</option><?php foreach($available as $candidate):?><option value="<?=$candidate['id']?>"><?=htmlspecialchars($candidate['name'])?></option><?php endforeach;?></select><button class="v-btn v-btn-outline">Asignar al proceso</button></form>
<details class="v-disclosure" style="margin-top:18px"><summary>Crear nuevo Ministro de Fe y asignarlo</summary>
<form method="post" class="v-stack" style="margin-top:12px"><?=Csrf::input()?>
<input type="hidden" name="action" value="create_assign">
<label>Nombre completo<input class="v-field" name="name" maxlength="150" required></label>
<label>Correo electrónico<input class="v-field" name="email" type="email" required></label>
<label>Contraseña inicial<input class="v-field" name="password" type="password" minlength="8" autocomplete="new-password" required></label>
<p class="v-muted">Se creará una cuenta de Ministro de Fe en esta organización y quedará asignada automáticamente a esta votación. Para reutilizar una cuenta existente, utiliza el selector superior.</p>
<button class="v-btn v-btn-orange" type="submit">Crear y asignar Ministro de Fe</button>
</form></details><?php endif;?></section>
<?php if($user['role']==='witness'):?><aside class="v-card v-pad"><div class="v-kicker">Siguiente hito</div><?php if($nextStage):?><h2><?=htmlspecialchars($stageLabels[$nextStage])?></h2><p class="v-muted"><?=$canCertifyNext?'El sistema validará y registrará una nueva evidencia SHA-256.':'Este hito se habilitará cuando la votación alcance el estado correspondiente.'?></p><?php if($canCertifyNext):?><form method="post"><?=Csrf::input()?><input type="hidden" name="action" value="checkpoint"><input type="hidden" name="stage" value="<?=htmlspecialchars($nextStage)?>"><button class="v-btn v-btn-orange">⚖ Certificar este hito</button></form><?php else:?><button class="v-btn v-btn-outline" disabled>Esperando cambio de estado</button><?php endif;?><?php else:?><h2>Fiscalización completada</h2><p class="v-muted">Todos los hitos fueron registrados.</p><?php endif;?></aside><?php else:?><aside class="v-card v-pad"><h2>Separación de funciones</h2><p class="v-muted">Solo el administrador asigna responsables. Solo cada Ministro de Fe puede certificar sus propios hitos.</p></aside><?php endif;?></div>
<section class="v-card v-pad v-table-wrap" style="margin-top:20px"><div class="v-section-head"><h2>Cadena de evidencias</h2><a class="v-btn v-btn-outline" href="/results.php?election_id=<?=$id?>">Revisar resultados</a></div><table class="v-table"><thead><tr><th>Fecha</th><th>Hito</th><th>Ministro de Fe</th><th>SHA-256</th></tr></thead><tbody><?php foreach($checks as $check):?><tr><td><?=htmlspecialchars($check['created_at'])?></td><td><?=htmlspecialchars($stageLabels[$check['stage']]??$check['stage'])?></td><td><?=htmlspecialchars($check['user_name'])?></td><td><code><?=htmlspecialchars($check['sha256_hash'])?></code></td></tr><?php endforeach;?><?php if(!$checks):?><tr><td colspan="4" class="v-muted">Sin hitos certificados todavía.</td></tr><?php endif;?></tbody></table></section>
</main></div></div></body></html>
